// The kit's React context: the film time of the frame being drawn, the frame's size, and the brand's tokens and look.
// ActRoot fills it from Remotion's clock; tests and review sheets can fill it directly with <KitProvider>. Components
// only ever read it through these hooks, so none of them knows a frame size or a rate of its own.
import React, {createContext, useContext} from 'react';
import {brandPack} from './core/brand';
import {fps, frameSize, secOf} from './core/film';
import {look as lookOfBrand, lookOf, type Look} from './core/looks';
import {cssVars, tokens as tokensOf, typeStyle, type ResolvedTypeStyle, type Tokens} from './core/tokens';

export type KitState = {
  /** film seconds of the frame being drawn (sub-frame accurate) */
  t: number;
  /** the same as a (fractional) film frame */
  frame: number;
  /** motion-blur sub-samples per master frame */
  sub: number;
  width: number;
  height: number;
  short: number;
  tokens: Tokens;
  look: Look;
};

const Ctx = createContext<KitState | null>(null);

function defaults(): KitState {
  const size = frameSize();
  const pack = brandPack();
  return {t: 0, frame: 0, sub: 1, width: size.width, height: size.height, short: size.short, tokens: tokensOf(pack), look: lookOfBrand(pack)};
}

export type KitProviderProps = {
  /** film seconds, or a film frame (one of the two) */
  t?: number;
  frame?: number;
  sub?: number;
  width?: number;
  height?: number;
  /** a look id to use instead of the brand's (review sheets show every look) */
  look?: string;
  children?: React.ReactNode;
};

/** Put the kit's clock, size, tokens and look in context. Anything not given comes from the parent or the film. */
export function KitProvider({t, frame, sub, width, height, look, children}: KitProviderProps) {
  const parent = useContext(Ctx);
  const pack = brandPack();
  let w = width ?? parent?.width;
  let h = height ?? parent?.height;
  if (w === undefined || h === undefined) {
    const s = frameSize();
    w = w ?? s.width;
    h = h ?? s.height;
  }
  const fr = frame ?? (t !== undefined ? t * safeFps() : parent?.frame ?? 0);
  const time = t ?? (frame !== undefined ? secOf(frame) : parent?.t ?? 0);
  const value: KitState = {
    t: time,
    frame: fr,
    sub: sub ?? parent?.sub ?? 1,
    width: w,
    height: h,
    short: Math.min(w, h),
    tokens: tokensOf(pack),
    look: look ? lookOf({...pack, look}).look : parent?.look ?? lookOfBrand(pack),
  };
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

function safeFps(): number {
  try {
    return fps();
  } catch {
    return 1;
  }
}

/** Everything in context (outside a provider: the film's size and brand at t = 0). */
export function useKit(): KitState {
  return useContext(Ctx) ?? defaults();
}

/** Film seconds of the frame being drawn, sub-frame accurate. */
export const useFilmTime = (): number => useKit().t;
/** The film frame being drawn (fractional for motion-blur sub-samples). */
export const useFilmFrame = (): number => useKit().frame;
/** The frame's size, with its short and long sides. */
export function useFrameSize(): {width: number; height: number; short: number; long: number; cx: number; cy: number} {
  const k = useKit();
  return {width: k.width, height: k.height, short: k.short, long: Math.max(k.width, k.height), cx: k.width / 2, cy: k.height / 2};
}
/** The brand's tokens. */
export const useTokens = (): Tokens => useKit().tokens;
/** The look in force. */
export const useLook = (): Look => useKit().look;

/**
 * Px for a length given as a fraction of the frame's short side, so every size follows the film's frame: `u(0.028)` is
 * body text on any frame.
 */
export function useUnit(): (fraction: number) => number {
  const s = useKit().short;
  return (fraction: number) => fraction * s;
}

/**
 * One app pixel at film scale: app screens are shown at twice their size on a frame whose short side is 1080 lines,
 * so text authored at the app's sizes clears the read-time minimum. Scales with the frame.
 */
export function useAppPx(): (appPx: number) => number {
  const s = useKit().short;
  return (appPx: number) => (appPx * s) / 540;
}

/**
 * The look's accent-line weight in px on this frame (the look's `line`, a fraction of the short side). Every kit
 * component that draws the accent line takes it by default (the charts' curves and lines, the logo build's outline), so
 * an act's own line and the kit component it hands to share one weight: the films' 4 px logo-build line once met a 3 px
 * line an act drew itself (L-kit-D131).
 */
export function useLine(): number {
  const k = useKit();
  return k.look.line * k.short;
}

/** A type role as CSS, sized for this frame. */
export function useType(role: string, color?: string): ResolvedTypeStyle {
  const k = useKit();
  return typeStyle(k.tokens, role, k.short, color);
}

// The root of every act composition: turns Remotion's frame into film time, including the motion-blur sub-samples,
// loads and checks the brand's fonts before the first frame, and puts the kit in context.
//
// Frame 0 of an act composition is its first shot's first film frame. With sub > 1 each master frame is drawn `sub`
// times across the shutter (180° by default, centred on the frame: phase −90°), and the renderer averages them into
// true motion blur. Every scene is a pure function of film time, so any frame renders alone.
import React from 'react';
import {useCurrentFrame, useVideoConfig} from 'remotion';
import {actSpan, fps, frameSize, shot} from './core/film';
import {KitProvider, TokenScope} from './context';
import {FontGate} from './fonts';

export type ActRootProps = {
  /** the act (its first shot is frame 0) … */
  act?: number | string;
  /** … or the first shot, by id */
  firstShot?: string;
  /** motion-blur sub-samples per master frame (1 = none) */
  sub?: number;
  /** shutter angle in degrees (180 is film-standard) */
  shutter?: number;
  /** load and check the brand's fonts before the first frame (default on) */
  fonts?: boolean;
  /** put the brand's tokens on the page as CSS variables (default on) */
  cssVars?: boolean;
  children?: React.ReactNode;
};

/** The film frame a composition frame draws, for `sub` samples across a shutter of `shutter` degrees. */
export function filmFrameOf(compositionFrame: number, firstFrame: number, sub = 1, shutter = 180): number {
  const S = Math.max(1, Math.round(sub));
  const f = Math.floor(compositionFrame / S);
  const k = compositionFrame % S;
  const local = S === 1 ? f : f + (shutter / 360) * ((k + 0.5) / S - 0.5);
  return firstFrame + local;
}

export function ActRoot({act, firstShot, sub = 1, shutter = 180, fonts = true, cssVars = true, children}: ActRootProps) {
  const F = useCurrentFrame();
  const {width, height} = useVideoConfig();
  const first = firstShot ?? (act !== undefined ? actSpan(act)?.first : undefined);
  const start = first ? shot(first).frameIn : 0;
  const frame = filmFrameOf(F, start, sub, shutter);
  const body = cssVars ? <TokenScope>{children}</TokenScope> : children;
  return (
    <FontGate enabled={fonts}>
      <KitProvider frame={frame} sub={Math.max(1, Math.round(sub))} width={width} height={height}>
        {body}
      </KitProvider>
    </FontGate>
  );
}

export type CompositionSpec = {id: string; durationInFrames: number; fps: number; width: number; height: number; defaultProps: {sub: number}};

/**
 * What to register for an act (the engine's generated Root uses this, so an act's length, rate and size have one
 * source): its length in master frames × sub, the film's rate and size.
 */
export function actComposition(act: number | string, opts: {sub?: number; id?: string} = {}): CompositionSpec | null {
  const span = actSpan(act);
  if (!span) return null;
  const sub = Math.max(1, Math.round(opts.sub ?? 1));
  const size = frameSize();
  return {id: opts.id ?? `Act${act}`, durationInFrames: span.frames * sub, fps: fps(), width: size.width, height: size.height, defaultProps: {sub}};
}

// A placeholder act: every shot of an act as a labelled box with its timing, so the act renders from day one and a
// builder always has a first working version on disk. It shows the shot, its frames and timecode, its on-screen text,
// its read with the word being said picked out, a progress bar through the shot, and the act's shots as a strip with
// the playhead. The engine's generated entry uses it for any act whose scene isn't written yet.
import {AbsoluteFill} from 'remotion';
import {actShots, actSpan, hasWords, secOf, shot as shotOf, timecode, voLead, filmData, type Shot} from './core/film';
import {clamp01} from './core/spline';
import {useFilmFrame, useFilmTime, useFrameSize, useTokens, useType} from './context';
import {Ground} from './paper';

function currentShot(list: Shot[], frame: number): Shot | null {
  let hit: Shot | null = list[0] ?? null;
  for (const s of list) if (s.frameIn <= frame) hit = s;
  return hit;
}

/**
 * The read of a shot with the word being said at t picked out (from vo_words; the plain line when there are none).
 * Only the colour changes: a word that turned bold would widen and push every word after it sideways a pixel or so,
 * and the line would jitter on every word (the render-stability check flags it as snaps and relative motion).
 */
function Read({id, t}: {id: string; t: number}) {
  const tk = useTokens();
  const s = useType('body', tk.color.ink3);
  const words = filmData()?.vo_words?.shots?.[id]?.words ?? [];
  const sh = shotOf(id);
  if (!hasWords(id)) return <div style={s}>{sh.vo}</div>;
  const base = sh.start + voLead(id);
  return (
    <div style={s}>
      {words.map((w, i) => {
        const on = t >= base + w.start && t < base + w.end;
        const said = t >= base + w.end;
        return (
          <span key={i} style={{color: on ? tk.color.accentInk : said ? tk.color.ink2 : undefined}}>
            {w.w}
            {i < words.length - 1 ? ' ' : ''}
          </span>
        );
      })}
    </div>
  );
}

export function PlaceholderAct({act, note}: {act: number | string; note?: string}) {
  const t = useFilmTime();
  const frame = useFilmFrame();
  const {width, height, short} = useFrameSize();
  const tk = useTokens();
  const eyebrow = useType('eyebrow');
  const h1 = useType('h1', tk.color.ink);
  const h2 = useType('h2', tk.color.ink2);
  const mono = useType('mono');
  const list = actShots(act);
  const span = actSpan(act);
  const cur = currentShot(list, Math.floor(frame));
  if (!cur || !span) {
    return (
      <AbsoluteFill>
        <Ground />
        <div style={{...h2, position: 'absolute', left: 0.08 * width, top: 0.1 * height}}>Act {String(act)} has no shots in timing/shots.json.</div>
      </AbsoluteFill>
    );
  }
  const pad = 0.07 * short;
  const within = clamp01((frame - cur.frameIn) / Math.max(1, cur.frames));
  const stripY = height - pad - 0.05 * short;
  const stripW = width - 2 * pad;
  return (
    <AbsoluteFill>
      <Ground />
      <div style={{position: 'absolute', left: pad, top: pad, right: pad}}>
        <div style={eyebrow}>
          Act {String(act)} · {span.first}–{span.last} · placeholder{note ? ` · ${note}` : ''}
        </div>
        <div style={{...h1, marginTop: 0.02 * short}}>{cur.id}</div>
        <div style={{...mono, marginTop: 0.012 * short}}>
          frames {cur.frameIn}–{cur.frameOut - 1} · {timecode(cur.frameIn)} · {cur.dur.toFixed(2)} s · now {timecode(Math.floor(frame))}
        </div>
        {cur.onScreen && <div style={{...h2, marginTop: 0.03 * short}}>{cur.onScreen}</div>}
        <div style={{marginTop: 0.03 * short, maxWidth: 0.8 * width}}>
          <Read id={cur.id} t={t} />
        </div>
      </div>
      <div style={{position: 'absolute', left: pad, top: stripY - 0.02 * short, width: stripW, height: 0.006 * short, background: tk.color.hairline, borderRadius: short}}>
        <div style={{width: `${within * 100}%`, height: '100%', background: tk.color.accent, borderRadius: short}} />
      </div>
      <div style={{position: 'absolute', left: pad, top: stripY, width: stripW, height: 0.05 * short, display: 'flex', gap: 0.004 * short}}>
        {list.map((s) => {
          const active = s.id === cur.id;
          return (
            <div
              key={s.id}
              style={{
                ...mono,
                flex: `${s.frames} 0 0`,
                background: active ? tk.color.softAccent : tk.color.surface,
                boxShadow: `inset 0 0 0 ${Math.max(1, 0.0012 * short)}px ${active ? tk.color.accent : tk.color.hairline}`,
                borderRadius: 0.006 * short,
                display: 'flex',
                alignItems: 'center',
                paddingLeft: 0.008 * short,
                overflow: 'hidden',
                whiteSpace: 'nowrap',
                color: active ? tk.color.accentInk : tk.color.ink3,
              }}
            >
              {s.id}
            </div>
          );
        })}
